    imageFilteredSearchCreate: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description Forks from this pre-existing saved search. */
                    searchId?: number | string;
                    allwords?: string;
                    /**
                     * @default AND
                     * @enum {string}
                     */
                    allwordsMode?: "OR" | "AND";
                    /**
                     * @default [
                     *       "name",
                     *       "comment",
                     *       "file",
                     *       "author",
                     *       "tags",
                     *       "cat-title",
                     *       "cat-desc"
                     *     ]
                     */
                    allwordsFields?: ("name" | "comment" | "file" | "author" | "tags" | "cat-title" | "cat-desc")[];
                    tags?: (number | string)[];
                    /**
                     * @default AND
                     * @enum {string}
                     */
                    tagsMode?: "OR" | "AND";
                    categories?: (number | string)[];
                    /** @default false */
                    categoriesWithsubs?: boolean;
                    authors?: string[];
                    filetypes?: string[];
                    addedBy?: (number | string)[];
                    /** @enum {string} */
                    datePostedPreset?: "24h" | "7d" | "30d" | "3m" | "6m" | "custom" | "";
                    /** @description Required, non-empty, when `datePostedPreset` is `custom`. Each entry is `y<YYYY>`, `m<YYYY>-<MM>`, or `d<YYYY>-<MM>-<DD>`. */
                    datePostedCustom?: string[];
                    /** @enum {string} */
                    dateCreatedPreset?: "7d" | "30d" | "3m" | "6m" | "12m" | "custom" | "";
                    /** @description Same shape as `datePostedCustom`, required when `dateCreatedPreset` is `custom`. */
                    dateCreatedCustom?: string[];
                    ratios?: string[];
                    /** @description Only consulted when the gallery has rating enabled. */
                    ratings?: string[];
                    filesizeMin?: number;
                    filesizeMax?: number;
                    widthMin?: number;
                    widthMax?: number;
                    heightMin?: number;
                    heightMax?: number;
                };
            };
        };
        responses: {
            /** @description Search saved. */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        searchId: string;
                        /** Format: uri-reference */
                        searchUrl: string;
                    };
                };
            };
            400: components["responses"]["BadRequest"];
            422: components["responses"]["UnprocessableEntity"];
        };
    };
